function validate([edges]) {
  if (!Array.isArray(edges) || edges.length < 1 || edges.length > 99999) return 'edges needs 1 to 10^5 - 1 edges, as n is between 2 and 10^5.';
  const n = edges.length + 1;
  const root = Array.from({ length: n }, (_, i) => i);
  const find = x => {
    while (root[x] !== x) {
      root[x] = root[root[x]];
      x = root[x];
    }
    return x;
  };
  for (const edge of edges) {
    if (!Array.isArray(edge) || edge.length !== 2 || !edge.every(v => Number.isInteger(v) && v >= 0 && v < n)) return 'Each edge is [a, b] with 0 <= a, b < n, where n = edges.length + 1.';
    const ra = find(edge[0]);
    const rb = find(edge[1]);
    if (ra === rb) return 'The edges must form a tree: no cycles, loops or repeated edges.';
    root[ra] = rb;
  }
  return null;
}

