  const n = edges.length + 1;
  // Root the tree with a breadth-first search from 0 that rescans the whole edge list for every node.
  const up = new Array(n).fill(null);
  up[0] = -1;
  const queue = [0];
  for (let head = 0; head < queue.length; head++) {
    const node = queue[head];
    for (const [a, b] of edges) {
      const other = a === node ? b : b === node ? a : null;
      if (other !== null && up[other] === null) {
        up[other] = node;
        queue.push(other);
      }
    }
  }
  // A node's subtree holds every node whose path up to the root passes through it.
  const count = new Array(n).fill(0);
  for (let w = 0; w < n; w++) for (let u = w; u !== -1; u = up[u]) count[u]++;
  let good = 0;
  for (let v = 0; v < n; v++) {
    const sizes = [];
    for (let c = 0; c < n; c++) if (up[c] === v) sizes.push(count[c]);
    if (sizes.every(s => s === sizes[0])) good++;
  }
  return good;
}

