function generate(rand, size) {
  const int = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const large = size === 'large';
  const target = large ? int(1500, 2001) : int(2, 12);
  // up[i] < i describes a tree rooted at 0 before the labels are shuffled.
  const up = [-1];
  const shape = int(0, 4);
  if (shape === 3) {
    // Identical copies of one random subtree under the root: balanced, so many nodes are good.
    const copies = int(2, large ? 6 : 3);
    const m = Math.max(1, Math.floor((target - 1) / copies));
    const piece = [-1];
    for (let i = 1; i < m; i++) piece.push(rand() < 0.5 ? i - 1 : int(0, i - 1));
    for (let k = 0; k < copies; k++) {
      const base = up.length;
      for (let i = 0; i < m; i++) up.push(i === 0 ? 0 : base + piece[i]);
    }
  } else {
    const arity = int(2, 4);
    for (let i = 1; i < target; i++) {
      if (shape === 0) up.push(int(0, i - 1));
      else if (shape === 1) up.push(rand() < 0.8 ? i - 1 : int(0, i - 1));
      else if (shape === 2) up.push(Math.floor((i - 1) / arity));
      else up.push(rand() < 0.7 ? 0 : int(0, i - 1));
    }
  }
  const n = up.length;
  // Node 0 stays the root; every other label, the edge order and each edge's direction are shuffled.
  const label = Array.from({ length: n }, (_, i) => i);
  for (let i = n - 1; i > 1; i--) {
    const j = int(1, i);
    [label[i], label[j]] = [label[j], label[i]];
  }
  const edges = [];
  for (let i = 1; i < n; i++) edges.push(rand() < 0.5 ? [label[up[i]], label[i]] : [label[i], label[up[i]]]);
  for (let i = edges.length - 1; i > 0; i--) {
    const j = int(0, i);
    [edges[i], edges[j]] = [edges[j], edges[i]];
  }
  return [edges];
}
